#!/usr/bin/env bash
# Скачивает 12 последних постов @esh_setko (обложки 640x640) в esh_setko/photos.
# Ссылки на CDN Instagram подписаны и перестают работать примерно 5 ноября 2026.
# Запуск из корня репозитория: bash esh_setko/download_photos.sh
set -euo pipefail
dir="$(dirname "$0")/photos"
mkdir -p "$dir"

get() { curl -fsSL "$2" -o "$dir/$1.jpg" && echo "ok  $1"; }

